/**
 * The template library: structures (rings, functional groups, biomolecules, reagents) generated by
 * templates/build_library.py into ./library.json, plus the mechanism templates of ./catalog.ts.
 *
 * Structures are stored compactly (atoms + bonds, Ketcher units, y up, bond length 1.0, centred on
 * the origin) and turned into KET only when inserted. Everything here is synchronous and offline.
 */

import type { Ketcher } from 'ketcher-core';
import { ketToScene } from '../scene/ketToScene';
import type { Point, Scene } from '../scene/types';
import { CATEGORY_LABEL, TEMPLATES } from './catalog';
import rawLibrary from './library.json';
import libraryCas from './library-cas.json';
import { allTemplateNames } from '../i18n/templateNames';

export type LibraryCategory = 'ring' | 'group' | 'bio' | 'reagent' | 'mechanism';
export type InsertMode = 'add' | 'replace';

/**
 * [label, x, y, displayed H count, formal charge, KET radical (1 singlet, 2 doublet, 3 triplet)].
 * Labels are element symbols, "R" (single R group) or "R1", "R2"... (several R groups).
 */
export type LibraryAtom = [string, number, number, number?, number?, number?];
/** [atom index, atom index, order (1-3), KET stereo (1 wedge, 6 hash; narrow end at the first atom)]. */
export type LibraryBond = [number, number, number, number?];

export interface LibraryMolecule {
  atoms: LibraryAtom[];
  bonds: LibraryBond[];
}

export interface LibraryEntry {
  /** Unique id (also the `data-id` of the tile). Mechanisms are prefixed `mech-`. */
  id: string;
  name: string;
  category: LibraryCategory;
  /** Sub-category shown as a section heading ("Amino acids", "Organic"...). */
  group: string;
  /** Synonyms, abbreviations and Catalan names (searched, not shown in tiles). */
  keywords: string[];
  /** Hill formula with charge suffix (e.g. C2H4O2, H3O+); absent for R-group fragments and mechanisms. */
  formula?: string;
  /** Formula as chemists usually write it (NaBH4, CH3MgBr); falls back to `formula`. */
  displayFormula?: string;
  /** Canonical SMILES (RDKit) of structures; R groups are `*`. */
  smiles?: string;
  /** CAS Registry Numbers (from PubChem synonyms; searchable). */
  cas?: string[];
  /** Mechanisms: what the template shows. */
  description?: string;
  /** What a plain click / Enter does. Mechanisms replace the canvas, structures are added to it. */
  defaultMode: InsertMode;
  /** Structures only. */
  mol?: LibraryMolecule;
  /** Mechanisms only: the KET file. */
  ket?: string;
}

interface StructureRecord {
  id: string;
  name: string;
  cat: Exclude<LibraryCategory, 'mechanism'>;
  group: string;
  kw: string[];
  formula?: string;
  fd?: string;
  smiles: string;
  atoms: LibraryAtom[];
  bonds: LibraryBond[];
}

export const LIBRARY_CATEGORIES: { id: LibraryCategory; label: string; keywords: string[] }[] = [
  { id: 'ring', label: 'Rings', keywords: ['rings', 'scaffolds', 'cycles', 'heterocycles', 'anells', 'cicles', 'heterocicles'] },
  { id: 'group', label: 'Functional groups', keywords: ['functional groups', 'grups funcionals'] },
  { id: 'bio', label: 'Biomolecules', keywords: ['biomolecules', 'biochemistry', 'biomolècules', 'bioquímica'] },
  { id: 'reagent', label: 'Reagents', keywords: ['reagents', 'small molecules', 'reactius', 'molècules petites'] },
  { id: 'mechanism', label: 'Mechanisms', keywords: ['mechanisms', 'reactions', 'mecanismes', 'reaccions'] },
];

export const CATEGORY_NAME: Record<LibraryCategory, string> = Object.fromEntries(
  LIBRARY_CATEGORIES.map((c) => [c.id, c.label]),
) as Record<LibraryCategory, string>;

/** Extra (mostly Catalan) search terms for the mechanism templates of catalog.ts. */
const MECHANISM_KEYWORDS: Record<string, string[]> = {
  sn2: ['SN2', 'nucleophilic substitution', 'substitució nucleòfila', 'Walden inversion'],
  e2: ['E2', 'elimination', 'eliminació', 'anti-periplanar'],
  carbonyl_addition: ['nucleophilic addition', 'addició nucleòfila', 'cyanohydrin', 'cianohidrina'],
  eas_nitration: ['EAS', 'SEAr', 'electrophilic aromatic substitution', 'substitució electròfila aromàtica', 'nitració', 'arenium', 'Wheland'],
  diels_alder: ['cycloaddition', 'cicloaddició', 'pericyclic', 'pericíclica', '[4+2]'],
  radical_homolysis: ['homolysis', 'homòlisi', 'radical', 'fishhook', 'halogenation'],
  lewis_adduct: ['Lewis acid', 'Lewis base', 'adduct', 'àcid de Lewis', 'adducte'],
  pt_substitution: ['ligand substitution', 'substitució de lligands', 'associative', 'cisplatin', 'platí'],
  sicl4_hydrolysis: ['hydrolysis', 'hidròlisi', 'silicon', 'silici'],
  aqua_acidity: ['aqua ion', 'Brønsted acidity', 'acidesa', 'aquoió', 'ferro'],
  serine_protease: ['catalytic triad', 'tríada catalítica', 'protease', 'proteasa', 'chymotrypsin', 'quimotripsina', 'enzyme', 'enzim'],
  adh_hydride: ['hydride transfer', "transferència d'hidrur", 'NAD+', 'dehydrogenase', 'deshidrogenasa', 'enzyme', 'enzim'],
  kinase: ['phosphoryl transfer', 'fosforilació', 'ATP', 'cinasa', 'quinasa', 'enzyme', 'enzim'],
};

const STRUCTURES: LibraryEntry[] = (rawLibrary as unknown as StructureRecord[]).map((r) => ({
  id: r.id,
  name: r.name,
  category: r.cat,
  group: r.group,
  keywords: [...r.kw, ...allTemplateNames(r.id)],
  formula: r.formula,
  displayFormula: r.fd ?? r.formula,
  smiles: r.smiles,
  cas: (libraryCas as Record<string, string[]>)[r.id],
  defaultMode: 'add',
  mol: { atoms: r.atoms, bonds: r.bonds },
}));

const MECHANISMS: LibraryEntry[] = TEMPLATES.map((t) => ({
  id: `mech-${t.id}`,
  name: t.title,
  category: 'mechanism',
  group: CATEGORY_LABEL[t.category],
  keywords: [t.id, 'mechanism', 'mecanisme', t.electrons, ...(t.electrons === '1e' ? ['single electron', 'radical'] : ['electron pair']),
    ...(MECHANISM_KEYWORDS[t.id] ?? []), ...allTemplateNames(`mech-${t.id}`)],
  description: t.description,
  defaultMode: 'replace',
  ket: t.ket,
}));

/** Every entry: structures first (by category, in generator order), then mechanisms. */
export const LIBRARY: LibraryEntry[] = [...STRUCTURES, ...MECHANISMS];

const BY_ID = new Map(LIBRARY.map((e) => [e.id, e]));
export const libraryEntry = (id: string): LibraryEntry | undefined => BY_ID.get(id);

// ------------------------------------------------------------------------------------------------
// Search
// ------------------------------------------------------------------------------------------------

const GREEK: Record<string, string> = { α: 'alpha', β: 'beta', γ: 'gamma', δ: 'delta', ω: 'omega' };

/** Lower case, no accents (benzè -> benze), Greek letters spelled out, punctuation -> spaces. */
export function normalizeText(s: string): string {
  return s
    .replace(/[αβγδω]/g, (c) => ` ${GREEK[c]} `)
    .replace(/·/g, '') // Catalan l·l
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[₀-₉]/g, (c) => String(c.charCodeAt(0) - 0x2080))
    .replace(/[⁺]/g, '+')
    .replace(/[^a-z0-9+]+/g, ' ')
    .trim();
}

interface Field {
  text: string;      // normalized
  compact: string;   // normalized without spaces ("n buli" -> "nbuli")
  words: string[];
  weight: number;
}

const field = (s: string, weight: number): Field => {
  const text = normalizeText(s);
  return { text, compact: text.replace(/ /g, ''), words: text.split(' ').filter(Boolean), weight };
};

const INDEX = new WeakMap<LibraryEntry, Field[]>();

function fieldsOf(e: LibraryEntry): Field[] {
  let f = INDEX.get(e);
  if (!f) {
    const cat = LIBRARY_CATEGORIES.find((c) => c.id === e.category);
    f = [
      field(e.name, 3),
      ...e.keywords.map((k) => field(k, 2)),
      ...(e.formula ? [field(e.formula, 2)] : []),
      ...(e.cas ?? []).map((c) => field(c, 2)),
      ...(e.displayFormula && e.displayFormula !== e.formula ? [field(e.displayFormula, 2)] : []),
      field(e.group, 2),
      field(cat?.label ?? '', 1),
      ...(cat?.keywords ?? []).map((k) => field(k, 1)),
      field(e.id.replace(/^mech-/, ''), 1),
    ].filter((x) => x.text);
    INDEX.set(e, f);
  }
  return f;
}

/** Optimal string alignment distance, giving up (returning max + 1) once it exceeds max. */
export function editDistance(a: string, b: string, max: number): number {
  if (Math.abs(a.length - b.length) > max) return max + 1;
  let prev2: number[] = [];
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    let rowMin = i;
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      let v = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) v = Math.min(v, prev2[j - 2] + 1);
      cur.push(v);
      rowMin = Math.min(rowMin, v);
    }
    if (rowMin > max) return max + 1;
    prev2 = prev;
    prev = cur;
  }
  return prev[b.length];
}

function tokenScore(token: string, f: Field): number {
  if (f.compact === token || f.text === token) return 10;
  if (f.words.includes(token)) return 8;
  if (f.compact.startsWith(token)) return 7;
  if (f.words.some((w) => w.startsWith(token))) return 6;
  if (token.length >= 3 && f.compact.includes(token)) return 3;
  if (token.length >= 4) {
    const max = token.length >= 7 ? 2 : 1;
    for (const w of f.words) {
      if (w.length < 3) continue;
      if (editDistance(token, w, max) <= max) return 2;
      if (w.length > token.length && editDistance(token, w.slice(0, token.length), max) <= max) return 2;
    }
  }
  return 0;
}

/** Relevance of an entry for a normalized query (0 = no match). */
export function scoreEntry(e: LibraryEntry, query: string): number {
  const q = normalizeText(query);
  if (!q) return 1;
  const fields = fieldsOf(e);
  let total = 0;
  for (const token of q.split(' ')) {
    let best = 0;
    for (const f of fields) best = Math.max(best, tokenScore(token, f) * f.weight);
    if (best === 0) return 0;
    total += best;
  }
  // Whole-query bonuses: the name, or a synonym / abbreviation / formula, is exactly what was typed.
  const name = normalizeText(e.name);
  const qc = q.replace(/ /g, '');
  if (name === q) total += 30;
  else if (fields.some((f) => f.weight >= 2 && (f.text === q || f.compact === qc))) total += 20;
  else if (name.startsWith(q)) total += 12;
  return total;
}

/**
 * Entries matching every word of `query` (accent-insensitive, prefix and typo tolerant), best first.
 * An empty query returns `entries` unchanged.
 */
export function searchLibrary(query: string, entries: LibraryEntry[] = LIBRARY): LibraryEntry[] {
  if (!normalizeText(query)) return entries;
  return entries
    .map((e, i) => ({ e, i, s: scoreEntry(e, query) }))
    .filter((x) => x.s > 0)
    .sort((a, b) => b.s - a.s || a.e.name.length - b.e.name.length || a.i - b.i)
    .map((x) => x.e);
}

// ------------------------------------------------------------------------------------------------
// Favourites and recently used (ids only, in localStorage; every access may throw)
// ------------------------------------------------------------------------------------------------

export const FAVOURITES_KEY = 'mechand.library.favourites';
export const RECENT_KEY = 'mechand.library.recent';
export const RECENT_MAX = 16;

export function loadIds(key: string): string[] {
  try {
    const raw = globalThis.localStorage?.getItem(key);
    const v: unknown = raw ? JSON.parse(raw) : [];
    return Array.isArray(v) ? [...new Set(v.filter((x): x is string => typeof x === 'string' && BY_ID.has(x)))] : [];
  } catch {
    return [];
  }
}

export function saveIds(key: string, ids: string[]): void {
  try {
    globalThis.localStorage?.setItem(key, JSON.stringify(ids));
  } catch {
    // Private mode, quota or disabled storage: favourites just aren't remembered.
  }
}

export const withRecent = (ids: string[], id: string, max = RECENT_MAX): string[] => [id, ...ids.filter((x) => x !== id)].slice(0, max);
export const toggledFavourite = (ids: string[], id: string): string[] => (ids.includes(id) ? ids.filter((x) => x !== id) : [...ids, id]);

// ------------------------------------------------------------------------------------------------
// KET
// ------------------------------------------------------------------------------------------------

type Json = Record<string, unknown>;

export interface KetOptions {
  /** Translation applied to every coordinate (KET units, y up). */
  dx?: number;
  dy?: number;
}

const r4 = (v: number) => Math.round(v * 1e4) / 1e4;

/** Connected components of a library molecule (salts become one KET molecule per ion). */
function components(m: LibraryMolecule): number[][] {
  const parent = m.atoms.map((_, i) => i);
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  for (const [a, b] of m.bonds) parent[find(a)] = find(b);
  const groups = new Map<number, number[]>();
  m.atoms.forEach((_, i) => {
    const r = find(i);
    groups.set(r, [...(groups.get(r) ?? []), i]);
  });
  return [...groups.values()];
}

function moleculeKet(m: LibraryMolecule, o: KetOptions): Json {
  const dx = o.dx ?? 0, dy = o.dy ?? 0;
  const doc: Json = {};
  const nodes: Json[] = [];
  components(m).forEach((idx, k) => {
    const local = new Map(idx.map((a, i) => [a, i]));
    const atoms = idx.map((a) => {
      const [label, x, y, , charge, radical] = m.atoms[a];
      const location = [r4(x + dx), r4(y + dy), 0];
      // "R" is a pseudo-atom (italic R); "R1", "R2"... are Ketcher R-group labels (portable R# atoms).
      const rg = /^R(\d+)$/.exec(label);
      const atom: Json = rg ? { type: 'rg-label', location, $refs: [`rg-${rg[1]}`] } : { label, location };
      if (charge) atom.charge = charge;
      if (radical) atom.radical = radical;
      return atom;
    });
    const bonds = m.bonds
      .filter(([a]) => local.has(a))
      .map(([a, b, order, stereo]) => {
        const bond: Json = { type: order, atoms: [local.get(a), local.get(b)] };
        if (stereo) bond.stereo = stereo;
        return bond;
      });
    nodes.push({ $ref: `mol${k}` });
    doc[`mol${k}`] = { type: 'molecule', atoms, bonds };
  });
  return { root: { nodes }, ...doc };
}

/** Moves every coordinate of a KET document (atoms, pluses, arrows) by (dx, dy). */
function translateKet(ket: string, o: KetOptions): string {
  const dx = o.dx ?? 0, dy = o.dy ?? 0;
  if (!dx && !dy) return ket;
  const doc = JSON.parse(ket) as Json;
  const move = (p: unknown) => {
    if (Array.isArray(p) && typeof p[0] === 'number' && typeof p[1] === 'number') {
      p[0] = r4(p[0] + dx);
      p[1] = r4(p[1] + dy);
    } else if (p && typeof p === 'object' && typeof (p as Json).x === 'number' && typeof (p as Json).y === 'number') {
      (p as Json).x = r4(((p as Json).x as number) + dx);
      (p as Json).y = r4(((p as Json).y as number) + dy);
    }
  };
  const root = doc.root as Json | undefined;
  for (const node of (root?.nodes as Json[] | undefined) ?? []) {
    if (typeof node.$ref === 'string') {
      const mol = doc[node.$ref] as Json | undefined;
      for (const a of (mol?.atoms as Json[] | undefined) ?? []) move(a.location);
    } else if (node.type === 'plus') {
      move(node.location);
    } else if (node.type === 'arrow') {
      for (const p of ((node.data as Json | undefined)?.pos as unknown[] | undefined) ?? []) move(p);
    }
  }
  return JSON.stringify(doc);
}

/** KET text for an entry, optionally translated. */
export function entryKet(entry: LibraryEntry, opts: KetOptions = {}): string {
  if (entry.ket) return translateKet(entry.ket, opts);
  if (entry.mol) return JSON.stringify(moleculeKet(entry.mol, opts));
  throw new Error(`Library entry ${entry.id} has no structure`);
}

// ------------------------------------------------------------------------------------------------
// Placement and insertion
// ------------------------------------------------------------------------------------------------

export interface Bounds {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
}

function boundsOf(points: Point[]): Bounds | null {
  if (!points.length) return null;
  return {
    minX: Math.min(...points.map((p) => p.x)),
    minY: Math.min(...points.map((p) => p.y)),
    maxX: Math.max(...points.map((p) => p.x)),
    maxY: Math.max(...points.map((p) => p.y)),
  };
}

export const sceneBounds = (s: Scene): Bounds | null =>
  boundsOf([...s.atoms, ...s.pluses, ...s.arrows.flatMap((a) => [a.start, a.end])]);

export function entryBounds(entry: LibraryEntry): Bounds | null {
  if (entry.mol) return boundsOf(entry.mol.atoms.map(([, x, y]) => ({ x, y })));
  return entry.ket ? sceneBounds(ketToScene(entry.ket)) : null;
}

/** Gap (in bond lengths) between the existing drawing and an added fragment. */
export const ADD_GAP = 2;

/**
 * Translation that puts a fragment with bounds `frag` to the right of the existing drawing
 * `canvas`, vertically centred on it (no translation when the canvas is empty).
 */
export function placementOffset(canvas: Bounds | null, frag: Bounds | null): { dx: number; dy: number } {
  if (!canvas || !frag) return { dx: 0, dy: 0 };
  return {
    dx: canvas.maxX + ADD_GAP - frag.minX,
    dy: (canvas.minY + canvas.maxY) / 2 - (frag.minY + frag.maxY) / 2,
  };
}

export type KetcherLike = Pick<Ketcher, 'getKet' | 'setMolecule' | 'addFragment'>;

/**
 * Inserts a library entry into Ketcher.
 *   - 'replace': ketcher.setMolecule(ket) (the canvas is cleared first, as the old Templates menu did);
 *   - 'add':     ketcher.addFragment(ket), placed to the right of what is already drawn (vertically
 *                centred on it), so that nothing overlaps; Ketcher then re-centres the view.
 */
export async function insertTemplate(ketcher: KetcherLike, entry: LibraryEntry, mode: InsertMode = entry.defaultMode): Promise<void> {
  if (mode === 'replace') {
    await ketcher.setMolecule(entryKet(entry));
    return;
  }
  let canvas: Bounds | null = null;
  try {
    canvas = sceneBounds(ketToScene(await ketcher.getKet()));
  } catch {
    canvas = null; // unreadable canvas: insert at the fragment's own coordinates
  }
  await ketcher.addFragment(entryKet(entry, placementOffset(canvas, entryBounds(entry))));
}
